                if (entry.commitOrdinal() <= 0 || entry.commitOrdinal() > snapshot.lastCommitOrdinal()) throw new IOException("Invalid ordinal");
                if (entry.receiptReviewId() != null) require(view, "RECEIPT_REVIEW", entry.receiptReviewId());
