package nz.ac.aut.pdc.supermarket.catalog;

import java.math.BigDecimal;
import java.math.RoundingMode;

public record Product(String barcode, String name, String unit, BigDecimal sellingPrice, String zeroPriceNote) {
    public Product {
        if (barcode == null || !barcode.matches("[0-9]{8,14}") || name == null || name.isBlank() || unit == null || unit.isBlank())
            throw new IllegalArgumentException("Barcode/name/unit required");
        if (sellingPrice == null || sellingPrice.signum() < 0 || sellingPrice.compareTo(new BigDecimal("999999.99")) > 0)
            throw new IllegalArgumentException("Price outside 0–999999.99");
        sellingPrice = sellingPrice.setScale(2, RoundingMode.UNNECESSARY);
        if (sellingPrice.signum() == 0 && (zeroPriceNote == null || zeroPriceNote.isBlank()))
            throw new IllegalArgumentException("Zero price note required");
    }
}
package nz.ac.aut.pdc.supermarket.promotion;

import java.math.*;
import java.time.*;
import java.util.*;
import nz.ac.aut.pdc.shared.IdClock;

public record Promotion(String promotionId, Kind kind, BigDecimal payPercent, BigDecimal threshold,
                        BigDecimal reduction, Integer priority, String startsOn, String endsOn, Set<String> barcodes) {
    public enum Kind { PERCENT, REDUCTION }
    public Promotion {
        if (promotionId == null || promotionId.isBlank() || kind == null) throw new IllegalArgumentException("Activity ID/kind required");
        if (LocalDate.parse(startsOn).isAfter(LocalDate.parse(endsOn))) throw new IllegalArgumentException("Invalid activity dates");
        barcodes = Set.copyOf(barcodes);
        if (barcodes.isEmpty()) throw new IllegalArgumentException("Explicit applicable products required");
        if (kind == Kind.PERCENT) {
            if (payPercent == null || payPercent.compareTo(BigDecimal.ONE) < 0 || payPercent.compareTo(new BigDecimal("99")) > 0)
                throw new IllegalArgumentException("Pay percentage must be 1–99");
            payPercent = payPercent.stripTrailingZeros();
            if (threshold != null || reduction != null) throw new IllegalArgumentException("Unexpected reduction fields");
        } else {
            if (threshold == null || reduction == null || threshold.signum() <= 0 || reduction.signum() <= 0 || reduction.compareTo(threshold) > 0)
                throw new IllegalArgumentException("Invalid threshold/reduction");
            threshold = threshold.setScale(2, RoundingMode.UNNECESSARY); reduction = reduction.setScale(2, RoundingMode.UNNECESSARY);
            if (payPercent != null) throw new IllegalArgumentException("Unexpected pay percentage");
        }
    }
    public boolean active(Instant now) {
        Instant start = LocalDate.parse(startsOn).atStartOfDay(IdClock.BUSINESS_ZONE).toInstant();
        Instant followingMidnight = LocalDate.parse(endsOn).plusDays(1).atStartOfDay(IdClock.BUSINESS_ZONE).toInstant();
        return !now.isBefore(start) && now.isBefore(followingMidnight);
    }
}
package nz.ac.aut.pdc.infrastructure;

import com.fasterxml.jackson.databind.node.ObjectNode;
import nz.ac.aut.pdc.shared.*;
import java.time.Instant;
import java.util.*;

/** Explicit server-managed field assignment. Historical and user-input dates are never stripped. */
final class SubmissionTime {
    private SubmissionTime() {}
    static ChangeSet assign(WorkingCopy baseline, ChangeSet changes, Instant acceptedAt) {
        String time = acceptedAt.toString();
        List<RecordData> inserts = new ArrayList<>();
        for (RecordData r : changes.inserts()) {
            ObjectNode data = (ObjectNode) r.data();
            switch (r.table()) {
                case "DOCUMENT" -> {
                    data.put("createdAt", time);
                    if (Set.of("CONFIRMED", "APPROVED").contains(data.path("status").asText())
                        || data.hasNonNull("confirmedAt")) data.put("confirmedAt", time);
                }
                case "DOC_EVENT" -> data.put("occurredAt", time);
                case "RECEIPT_REVIEW" -> data.put("reviewedAt", time);
                default -> { }
            }
            // Keep untouched payload bytes stable, including BigDecimal representation.
            boolean managed = Set.of("DOCUMENT", "DOC_EVENT", "RECEIPT_REVIEW").contains(r.table());
            inserts.add(managed ? new RecordData(r.table(),r.id(),r.version(),JsonCodec.write(data)) : r);
        }
        List<ChangeSet.Patch> patches = new ArrayList<>();
        for (ChangeSet.Patch p : changes.patches()) {
            if (!p.table().equals("DOCUMENT")) { patches.add(p); continue; }
            RecordData old = baseline.find(p.table(),p.id()).orElseThrow(() -> new IllegalArgumentException("REFERENCE_INVALID"));
            ObjectNode fields = (ObjectNode) JsonCodec.tree(p.changedFields());
            if (fields.has("createdAt") && !fields.get("createdAt").equals(old.data().path("createdAt")))
                throw new IllegalArgumentException("INVALID_INPUT");
            if (old.data().hasNonNull("confirmedAt")) {
                if (fields.has("confirmedAt") && !fields.get("confirmedAt").equals(old.data().get("confirmedAt")))
                    throw new IllegalArgumentException("INVALID_INPUT");
            } else if (fields.has("confirmedAt") || Set.of("CONFIRMED","APPROVED").contains(fields.path("status").asText())) {
                fields.put("confirmedAt", time);
            }
            patches.add(new ChangeSet.Patch(p.table(),p.id(),p.expectedVersion(),JsonCodec.write(fields)));
        }
        return new ChangeSet(inserts,patches,changes.removals());
    }
}
package nz.ac.aut.pdc.shared;

import java.util.List;
