package nz.ac.aut.pdc.supermarket.app;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import nz.ac.aut.pdc.infrastructure.*;
import nz.ac.aut.pdc.shared.*;
import nz.ac.aut.pdc.shared.OperationContext.*;
import nz.ac.aut.pdc.shared.SubmissionPort.*;
import nz.ac.aut.pdc.supermarket.auth.*;
import nz.ac.aut.pdc.supermarket.aftersale.*;
import nz.ac.aut.pdc.supermarket.stock.SharedStockAdapter;
import nz.ac.aut.pdc.supermarket.sales.OriginalSaleAccess;
import nz.ac.aut.pdc.supermarket.cui.*;

/** A-owned assembly of delivered B services; B internals remain untouched. */
public final class RepositoryBIntegration implements BIntegration {
    private final List<JsonStore.Credential> accounts;
    private final SharedStockAdapter stock=new SharedStockAdapter();
    private AuthService auth;
    private Supplier<List<JsonStore.Credential>> credentialView;
    public RepositoryBIntegration(List<JsonStore.Credential> accounts) { this.accounts=List.copyOf(accounts); }
    public AuthService auth() { return Objects.requireNonNull(auth,"Application not initialized"); }
    @Override public IdentityResolver identities(Supplier<List<JsonStore.Credential>> credentials) {
        credentialView=credentials;
        auth=new LocalAuthService(new SharedCredentialStore(credentials),new Sha256PasswordHasher());
        return new SharedIdentityResolver(auth);
    }
    @Override public AOperations.StockDependency stock() { return stock; }
    @Override public List<JsonStore.Credential> initialAccounts() { return accounts; }
    @Override public JsonStore.IntegrityValidator integrity() { return new AftersaleIntegrityValidator(); }
    @Override public Map<String,CommitValidator> validators() {
        var registered=new HashMap<>(BCommitValidators.create(stock));
        // There is one production read admission. The older B trace-only operation is not registered.
        registered.remove(AftersaleDraftOperations.READ);
        return Map.copyOf(registered);
    }
    @Override public OriginalSaleAccess.DraftAccess drafts() {
        CommitValidator bRead=new AftersaleDraftValidator(AftersaleDraftOperations.READ);
        return new OriginalSaleAccess.DraftAccess() {
            private OperationContext context(OperationContext o) {
                return new OperationContext(o.sessionRef(),o.requestKey(),AftersaleDraftOperations.READ,o.targetId());
            }
            @Override public Result<ChangeSet> prepareTarget(OperationContext op,ActorContext actor,AftersaleReadRequest request,WorkingCopy wc) {
                if (wc.find("DOCUMENT",request.aftersaleId()).isEmpty())
                    return Result.rejected("DRAFT_REQUIRED","Create the target using B AftersaleDraftService before IF-11");
                // Ask B's existing pure validator for target authorization, including on replay.
                String first=request.saleLineIds().isEmpty() ? wc.records("DOC_LINE").stream()
                    .filter(r -> r.data().path("documentId").asText().equals(request.voucher())).map(RecordData::id).sorted().findFirst().orElse("") : request.saleLineIds().get(0);
                var probe=ChangeSet.empty();
                probe=new ChangeSet(List.of(RecordData.of("DOC_EVENT","admission-only",new DocEvent("admission-only",request.aftersaleId(),1,
                    AftersaleReadRequest.OPERATION,actor.accountId(),null,JsonCodec.write(Map.of("originalSaleLineId",first))))),List.of());
                var check=bRead.validate(context(op),actor,JsonCodec.BusinessRequest.of(request),wc,probe,Instant.EPOCH);
                return check.hasValue() ? Result.prepared(ChangeSet.empty()) : check.failure();
            }
            @Override public Result<Void> reviewTarget(OperationContext op,ActorContext actor,AftersaleReadRequest request,WorkingCopy wc,ChangeSet complete,Instant time) {
                return bRead.validate(context(op),actor,JsonCodec.BusinessRequest.of(request),wc,complete,time);
            }
        };
    }
    public Operations cuiOperations(Application app) {
        Operations delivered=new SharedOperations(app.storage(),app.ids());
        return new Operations() {
            public OperationFeedback replenish(CuiActor actor,String barcode,int quantity) { return delivered.replenish(actor,barcode,quantity); }
            public OperationFeedback recordLoss(CuiActor actor,String barcode,nz.ac.aut.pdc.supermarket.stock.Position position,int quantity) { return delivered.recordLoss(actor,barcode,position,quantity); }
            public OperationFeedback cancelAftersaleDraft(CuiActor actor,String draft) { return delivered.cancelAftersaleDraft(actor,draft); }
            public OperationFeedback deleteAftersaleDraft(CuiActor actor,String draft) { return delivered.deleteAftersaleDraft(actor,draft); }
            public OperationFeedback reverseDocument(CuiActor actor,String target,String reason) { return delivered.reverseDocument(actor,target,reason); }
            public OperationFeedback aftersale(CuiActor actor,AftersaleRequest request) {
                return OperationFeedback.fail("售后菜单暂不可用：B SharedOperations 须改用 A OriginalSaleAccess 及凭证／原始请求重试契约；其他已接入功能可继续。");
            }
        };
    }
    @Override public void run(Application app) {
        if (credentialView.get().isEmpty()) {
            System.out.println("未配置预置账号，登录暂不可用；首次启动用 --accounts 指定本地凭证 JSON（只含哈希，不上传）。"); return;
        }
        System.out.println("A 服务已装配；B 菜单尚需接入商品／收货／促销／销售入口及新 IF-11。售后菜单暂不可用。");
        new CuiApp(auth(),cuiOperations(app),new InputValidator(),new BufferedReader(new InputStreamReader(System.in,StandardCharsets.UTF_8)),System.out).run();
    }
}

