            Instant acceptedAt) {
        Objects.requireNonNull(op, "op");
        Objects.requireNonNull(actor, "actor");
        Objects.requireNonNull(baseline, "baseline");
        Objects.requireNonNull(changes, "changes");

        RecordData baselineDocument = baseline.find("DOCUMENT", op.targetId()).orElse(null);
        final DocumentHeader header;
        if (baselineDocument != null
                && "DRAFT".equals(baselineDocument.as(DocumentHeader.class).status())) {
            if (!inserts(changes, "DOCUMENT").isEmpty()) {
                return Result.rejected("INVALID_INPUT", "Draft completion must patch the existing document");
            }
            ChangeSet.Patch patch = changes.patches().stream()
                    .filter(p -> p.table().equals("DOCUMENT") && p.id().equals(op.targetId()))
                    .findFirst().orElse(null);
            if (patch == null) {
                return Result.rejected("INVALID_INPUT", "Draft completion requires DOCUMENT patch");
            }
            ObjectNode fields = (ObjectNode) JsonCodec.tree(patch.changedFields());
            if (!"CONFIRMED".equals(fields.path("status").asText())) {
                return Result.rejected("INVALID_INPUT", "Draft completion must set CONFIRMED");
            }
            boolean traced = baseline.records("DOC_EVENT").stream()
                    .anyMatch(r -> r.as(DocEvent.class).documentId().equals(op.targetId())
                            && "READ_FOR_AFTERSALE".equals(r.as(DocEvent.class).action()));
            if (!traced) {
                return Result.rejected("DRAFT_HAS_NO_READ_TRACE",
                        "Aftersale completion requires saved read trace");
            }
            header = new DocumentHeader(
                    op.targetId(), "AFTERSALE", "CONFIRMED", op.requestKey(),
                    baselineDocument.as(DocumentHeader.class).requestFingerprint(),
                    baselineDocument.as(DocumentHeader.class).createdBy(),
                    baselineDocument.as(DocumentHeader.class).createdAt(),
                    actor.accountId(), null, null);
        } else {
            List<RecordData> documents = inserts(changes, "DOCUMENT");
            if (documents.size() != 1) {
                return Result.rejected("INVALID_INPUT", "Exactly one AFTERSALE document required");
            }
            try {
                header = documents.get(0).as(DocumentHeader.class);
            } catch (RuntimeException ex) {
                return Result.rejected("INVALID_INPUT", "Invalid AFTERSALE document");
            }
        }
        if (!"AFTERSALE".equals(header.kind()) || !"CONFIRMED".equals(header.status())) {
            return Result.rejected("INVALID_INPUT", "AFTERSALE document must be CONFIRMED");
        }
        if (!header.documentId().equals(op.targetId())) {
            return Result.rejected("REFERENCE_INVALID", "Operation target is not the aftersale document");
        }
        if (!actor.accountId().equals(header.confirmedBy())) {
            return Result.rejected("FORBIDDEN", "ConfirmedBy must be the authenticated actor");
        }
        if (request == null || acceptedAt == null) {
            return Result.rejected("INVALID_INPUT", "Original request and acceptedAt required");
        }
        final AftersaleCommand command;
        try {
            command = request.as(AftersaleCommand.class);
        } catch (RuntimeException ex) {
            return Result.rejected("INVALID_INPUT", "Invalid original aftersale request");
        }
        if (!command.requestKey().equals(op.requestKey())) {
            return Result.rejected("REQUEST_KEY_CONFLICT", "Original request key mismatch");
        }
        List<AftersaleCommandLine> unmatched = new ArrayList<>(command.lines());
        List<AftersaleCommandLine> exchanges = command.lines().stream()
                .filter(line -> line.kind() == RedemptionKind.EXCHANGE).toList();
        Map<String, AftersaleCommandLine> lineByRedemption = new HashMap<>();
        List<Redemption> redemptions = new ArrayList<>();
        for (RecordData record : inserts(changes, "REDEMPTION")) {
            final Redemption redemption;
            try {
                redemption = record.as(Redemption.class);
            } catch (RuntimeException ex) {
                return Result.rejected("INVALID_INPUT", "Cannot read redemption: " + ex.getMessage());
            }
            if (!header.documentId().equals(redemption.aftersaleId())) {
                return Result.rejected("REFERENCE_INVALID", "Redemption aftersaleId mismatch");
            }
            AftersaleCommandLine requestedLine = takeMatching(unmatched, redemption);
            if (requestedLine == null) {
                return Result.rejected("REFERENCE_INVALID",
                        "Redemption does not implement original request line");
            }
            lineByRedemption.put(redemption.redemptionId(), requestedLine);
            if (!redemption.redemptionId().equals(redemption.sourceLineId())) {
                return Result.rejected("REFERENCE_INVALID", "Redemption source line must be its business line");
            }
            if (redemption.amount().signum() < 0 || redemption.quantity() <= 0) {
                return Result.rejected("INVALID_INPUT", "Redemption amount/quantity invalid");
            }
            redemptions.add(redemption);
        }
        if (redemptions.isEmpty()) {
            return Result.rejected("INVALID_INPUT", "AfterSale requires at least one redemption");
        }
        if (!unmatched.isEmpty()) {
            return Result.rejected("REFERENCE_INVALID", "Some requested aftersale lines have no redemption");
        }
        Set<String> replacedRedemptions = new HashSet<>();
        for (RecordData record : inserts(changes, "REPLACEMENT")) {
            Replacement replacement = record.as(Replacement.class);
            if (!header.documentId().equals(replacement.aftersaleId())) {
                return Result.rejected("REFERENCE_INVALID", "Replacement aftersaleId mismatch");
            }
            AftersaleCommandLine requestedLine = lineByRedemption.get(replacement.redemptionId());
            if (requestedLine == null
                    || !Objects.equals(replacement.barcode(), requestedLine.replacementBarcode())
                    || replacement.quantity() != requestedLine.replacementQty()) {
                return Result.rejected("REFERENCE_INVALID", "Replacement does not implement original request");
            }
            if (!replacedRedemptions.add(replacement.redemptionId())) {
                return Result.rejected("INVALID_INPUT", "Duplicate replacement for redemption");
            }
            if (replacement.replacementAmount().signum() < 0) {
                return Result.rejected("INVALID_INPUT", "Replacement amount invalid");
            }
        }
        if (replacedRedemptions.size() != exchanges.size()) {
            return Result.rejected("REFERENCE_INVALID", "Every exchange line requires one replacement");
        }
        Result<Void> windowCheck = validateAftersaleWindow(baseline, redemptions, acceptedAt);
        if (!windowCheck.hasValue()) {
            return windowCheck;
        }

        Result<Void> stockCheck = stockAdapter.review(baseline, request, changes);
        if (!stockCheck.hasValue()) {
            return stockCheck;
        }
        return Result.value(null);
    }

    private AftersaleCommandLine takeMatching(
            List<AftersaleCommandLine> candidates, Redemption redemption) {
        for (int i = 0; i < candidates.size(); i++) {
            AftersaleCommandLine line = candidates.get(i);
            if (!line.saleLineId().equals(redemption.originalSaleLineId())
                    || line.kind() != redemption.kind()
                    || line.quantity() != redemption.quantity()
                    || line.opened() != redemption.opened()
                    || line.qualityProblem() != redemption.qualityProblem()) {
                continue;
            }
            if (line.reasonKind() == AftersaleReasonKind.OTHER
                    && !Objects.equals(line.reasonText(), redemption.reasonText())) {
                continue;
            }
            candidates.remove(i);
            return line;
        }
        return null;
    }

    private Result<Void> validateAftersaleWindow(
            WorkingCopy baseline, List<Redemption> redemptions, Instant acceptedAt) {
        ZoneId zone = ZoneId.of("Asia/Shanghai");
        LocalDate acceptedDate = acceptedAt.atZone(zone).toLocalDate();
        for (Redemption redemption : redemptions) {
            var saleLine = baseline.find("DOC_LINE", redemption.originalSaleLineId()).orElse(null);
            if (saleLine == null) {
                return Result.rejected("REFERENCE_INVALID", "Original sale line missing");
            }
            DocumentLine line = saleLine.as(DocumentLine.class);
            var document = baseline.find("DOCUMENT", line.documentId()).orElse(null);
            if (document == null) {
                return Result.rejected("REFERENCE_INVALID", "Original sale document missing");
            }
            DocumentHeader saleHeader = document.as(DocumentHeader.class);
            if (!"SALE".equals(saleHeader.kind()) || !"CONFIRMED".equals(saleHeader.status())
                    || saleHeader.confirmedAt() == null) {
                return Result.rejected("REFERENCE_INVALID", "Original line is not a confirmed sale");
            }
            LocalDate saleDate = Instant.parse(saleHeader.confirmedAt()).atZone(zone).toLocalDate();
            if (ChronoUnit.DAYS.between(saleDate, acceptedDate) > 30) {
                return Result.rejected("AFTERSALE_WINDOW_EXPIRED", "Outside 30-day aftersale window");
            }
        }
        return Result.value(null);
    }

    private List<RecordData> inserts(ChangeSet changes, String table) {
        return changes.inserts().stream().filter(r -> r.table().equals(table)).toList();
    }
}
package nz.ac.aut.pdc.supermarket.aftersale;

import java.util.Objects;

import nz.ac.aut.pdc.shared.ChangeSet;
import nz.ac.aut.pdc.shared.DocEvent;
import nz.ac.aut.pdc.shared.DocumentHeader;
import nz.ac.aut.pdc.shared.DocumentLine;
import nz.ac.aut.pdc.shared.JsonCodec;
import nz.ac.aut.pdc.shared.JsonCodec.BusinessRequest;
import nz.ac.aut.pdc.shared.MoneyEntry;
import nz.ac.aut.pdc.shared.OperationContext;
import nz.ac.aut.pdc.shared.RecordData;
import nz.ac.aut.pdc.shared.StockEntry;
import nz.ac.aut.pdc.shared.WorkingCopy;

/**
 * 把已校验的售后候选组装为 A 的统一 ChangeSet。
 *
 * <p>只组装，不保存/不提交；ID 由 B 侧稳定生成，commitOrdinal=0 由 IF-05 赋。
 * 表名/字段按 A handoff 与共享规范：DOCUMENT/AFTERSALE/DOC_LINE/DOC_EVENT/
 * REDEMPTION/REPLACEMENT/STOCK_ENTRY/MONEY_ENTRY。</p>
 */
public final class AftersaleChangeSetAssembler {

    public static final String OPERATION = "AFTERSALE";

    public ChangeSet assemble(
            AftersaleResult.Prepared prepared,
            String aftersaleId,
            OperationContext operation,
            OperationContext.ActorContext actor,
            BusinessRequest request) {
        Objects.requireNonNull(prepared, "prepared");
        Objects.requireNonNull(aftersaleId, "aftersaleId");
        Objects.requireNonNull(operation, "operation");
        Objects.requireNonNull(actor, "actor");
        Objects.requireNonNull(request, "request");

        ChangeSet.Builder out = new ChangeSet.Builder();
        String fingerprint = JsonCodec.fingerprint(operation.operation(), actor.accountId(), request);
        out.add(RecordData.of("DOCUMENT", aftersaleId, new DocumentHeader(
                aftersaleId, "AFTERSALE", "CONFIRMED", operation.requestKey(), fingerprint,
                actor.accountId(), null, actor.accountId(), null, null)));
        out.add(RecordData.of("AFTERSALE", aftersaleId, java.util.Map.of()));
        out.add(RecordData.of("DOC_EVENT", aftersaleId + "-EVENT", new DocEvent(
                aftersaleId + "-EVENT", aftersaleId, 1, "CONFIRM",
                actor.accountId(), null, "{}")));
        addFacts(out, prepared, aftersaleId, operation);
        return out.build();
    }

    /** 对已存在 DRAFT 的售后：补丁 DOCUMENT + 追加业务事实，不重复插入 DOCUMENT/AFTERSALE。 */
    public ChangeSet assembleForDraft(
            AftersaleResult.Prepared prepared,
            String aftersaleId,
            WorkingCopy baseline,
            OperationContext operation,
            OperationContext.ActorContext actor,
            BusinessRequest request) {
        Objects.requireNonNull(prepared, "prepared");
        Objects.requireNonNull(aftersaleId, "aftersaleId");
        Objects.requireNonNull(baseline, "baseline");
        Objects.requireNonNull(operation, "operation");
        Objects.requireNonNull(actor, "actor");
        Objects.requireNonNull(request, "request");

        RecordData document = baseline.find("DOCUMENT", aftersaleId)
                .orElseThrow(() -> new IllegalArgumentException("Draft document missing"));
        long nextEventVersion = baseline.records("DOC_EVENT").stream()
                .filter(r -> r.as(DocEvent.class).documentId().equals(aftersaleId))
                .mapToLong(r -> r.as(DocEvent.class).version())
                .max().orElse(0) + 1;
        ChangeSet.Builder out = new ChangeSet.Builder();
        out.patch(new ChangeSet.Patch("DOCUMENT", aftersaleId, document.version(),
                JsonCodec.write(java.util.Map.of(
                        "status", "CONFIRMED",
                        "confirmedBy", actor.accountId()))));
        out.add(RecordData.of("DOC_EVENT", aftersaleId + "-CONFIRM", new DocEvent(
                aftersaleId + "-CONFIRM", aftersaleId, nextEventVersion, "CONFIRM",
                actor.accountId(), null, "{}")));
        addFacts(out, prepared, aftersaleId, operation);
        return out.build();
    }

    private void addFacts(
            ChangeSet.Builder out,
            AftersaleResult.Prepared prepared,
            String aftersaleId,
            OperationContext operation) {
        for (Redemption redemption : prepared.redemptions()) {
            out.add(RecordData.of("DOC_LINE", redemption.redemptionId(), new DocumentLine(
                    redemption.redemptionId(), aftersaleId,
                    redemption.kind().name(), redemption.originalBarcode(), redemption.quantity())));
            out.add(RecordData.of("REDEMPTION", redemption.redemptionId(), redemption));
        }
        for (Replacement replacement : prepared.replacements()) {
            out.add(RecordData.of("DOC_LINE", replacement.lineId(), new DocumentLine(
                    replacement.lineId(), aftersaleId, "REPLACEMENT",
                    replacement.barcode(), replacement.quantity())));
            out.add(RecordData.of("REPLACEMENT", replacement.lineId(), replacement));
        }
        for (AftersaleResult.StockEntryView entry : prepared.stockEntries()) {
            String sourceLineId = sourceLineId(entry, prepared);
            out.add(RecordData.of("STOCK_ENTRY", entry.id(), new StockEntry(
                    entry.id(), sourceLineId,
                    StockEntry.Position.valueOf(entry.position().name()),
                    entry.delta(), entry.eventKey(), null, null, entry.transferKey(), 0)));
        }
        for (Settlement settlement : prepared.settlements()) {
            if (settlement.direction() == SettlementDirection.NONE) {
                continue;
            }
            java.math.BigDecimal signed = settlement.direction() == SettlementDirection.REFUND
                    ? settlement.amount().negate() : settlement.amount();
            String moneyId = settlement.redemptionId() + "-MONEY";
            out.add(RecordData.of("MONEY_ENTRY", moneyId, new MoneyEntry(
                    moneyId, aftersaleId, signed, operation.requestKey(), null)));
        }
    }

    private String sourceLineId(AftersaleResult.StockEntryView entry, AftersaleResult.Prepared prepared) {
        if (entry.transferKey() != null && !entry.transferKey().isBlank()) {
            return entry.transferKey();
        }
        for (Replacement replacement : prepared.replacements()) {
            if (replacement.barcode().equals(entry.barcode())) {
                return replacement.lineId();
            }
        }
        for (Redemption redemption : prepared.redemptions()) {
            if (redemption.originalBarcode().equals(entry.barcode())) {
                return redemption.redemptionId();
            }
        }
        throw new IllegalArgumentException("STOCK_ENTRY has no source line: " + entry.id());
    }
}

package nz.ac.aut.pdc.supermarket.aftersale;

import java.util.Objects;

import nz.ac.aut.pdc.shared.ChangeSet;
import nz.ac.aut.pdc.shared.JsonCodec.BusinessRequest;
import nz.ac.aut.pdc.shared.OperationContext;
import nz.ac.aut.pdc.shared.Result;
import nz.ac.aut.pdc.shared.SubmissionPort;
import nz.ac.aut.pdc.shared.WorkingCopy;
import nz.ac.aut.pdc.supermarket.auth.SharedRoles;
import nz.ac.aut.pdc.supermarket.stock.SharedWorkingCopyView;

/**
 * 售后提交入口：B 业务候选 → A 统一 ChangeSet → IF-05 提交。
 *
 * <p>先做 lookupResult 幂等查询再组装，符合 IF-05 单写者约定；不写文件、不嵌套 submit。</p>
 */
public final class AftersaleSubmissionService {

    private final AftersaleService aftersaleService;
    private final AftersaleChangeSetAssembler assembler;
    private final SubmissionPort store;

    public AftersaleSubmissionService(
            AftersaleService aftersaleService,
            AftersaleChangeSetAssembler assembler,
            SubmissionPort store) {
        this.aftersaleService = Objects.requireNonNull(aftersaleService, "aftersaleService");
        this.assembler = Objects.requireNonNull(assembler, "assembler");
        this.store = Objects.requireNonNull(store, "store");
    }

    public Result<SubmissionPort.CommitReceipt> submit(
            AftersaleCommand command,
            WorkingCopy workingCopy,
            OperationContext operation,
            OperationContext.ActorContext actor) {
        Objects.requireNonNull(command, "command");
        Objects.requireNonNull(workingCopy, "workingCopy");
        Objects.requireNonNull(operation, "operation");
        Objects.requireNonNull(actor, "actor");
        if (!command.requestKey().equals(operation.requestKey())) {
            return Result.rejected("INVALID_INPUT", "requestKey mismatch");
        }
        BusinessRequest request = BusinessRequest.of(command);
        Result<SubmissionPort.CommitReceipt> prior = store.lookupResult(operation, request);
        if (prior.status() != Result.Status.NOT_FOUND) {
            return prior;
        }
        if (operation.targetId() == null || operation.targetId().isBlank()) {
            return Result.rejected("INVALID_INPUT", "Aftersale target document id required");
        }

        AftersaleResult result = aftersaleService.apply(
                new SharedWorkingCopyView(workingCopy), command, SharedRoles.toLocal(actor.role()),
                operation.targetId());
        if (result instanceof AftersaleResult.Rejected rejected) {
            return Result.rejected(rejected.code(), rejected.message());
        }
        if (result instanceof AftersaleResult.Failed failed) {
            return Result.failed(failed.code(), failed.message());
        }
        AftersaleResult.Prepared prepared = (AftersaleResult.Prepared) result;
        if (prepared.redemptions().isEmpty()) {
            return Result.rejected("INVALID_INPUT", "Aftersale prepared no redemption");
        }
        ChangeSet changes;
        var existingDraft = workingCopy.find("DOCUMENT", operation.targetId());
        if (existingDraft.isPresent()
                && "DRAFT".equals(existingDraft.get().as(nz.ac.aut.pdc.shared.DocumentHeader.class).status())) {
            changes = assembler.assembleForDraft(
                    prepared, operation.targetId(), workingCopy, operation, actor, request);
        } else {
            changes = assembler.assemble(prepared, operation.targetId(), operation, actor, request);
        }
        return store.submit(operation, request, workingCopy, changes);
    }
}

package nz.ac.aut.pdc.supermarket.reversal;

import java.time.Instant;
import java.util.List;
import java.util.Objects;
import java.util.Set;

import com.fasterxml.jackson.databind.node.ObjectNode;

import nz.ac.aut.pdc.shared.ChangeSet;
import nz.ac.aut.pdc.shared.DocumentHeader;
import nz.ac.aut.pdc.shared.DocumentLine;
import nz.ac.aut.pdc.shared.JsonCodec;
import nz.ac.aut.pdc.shared.JsonCodec.BusinessRequest;
import nz.ac.aut.pdc.shared.MoneyEntry;
import nz.ac.aut.pdc.shared.OperationContext;
import nz.ac.aut.pdc.shared.RecordData;
import nz.ac.aut.pdc.shared.Result;
import nz.ac.aut.pdc.shared.StockEntry;
import nz.ac.aut.pdc.shared.SubmissionPort;
import nz.ac.aut.pdc.shared.WorkingCopy;
import nz.ac.aut.pdc.supermarket.aftersale.Effect;
import nz.ac.aut.pdc.supermarket.aftersale.Redemption;

/** 整单冲销六参校验器：权限、目标状态、完整反向关系与原子组。 */
public final class ReversalCommitValidator implements SubmissionPort.CommitValidator {

    private static final Set<String> INSERT_TABLES = Set.of(
            "DOCUMENT", "REVERSAL", "DOC_LINE", "DOC_EVENT",
            "STOCK_ENTRY", "MONEY_ENTRY", "REDEMPTION");

    @Override
    public Result<Void> validate(
            OperationContext op,
            OperationContext.ActorContext actor,
            BusinessRequest request,
            WorkingCopy baseline,
            ChangeSet changes,
            Instant acceptedAt) {
        if (actor == null || (actor.role() != OperationContext.Role.MANAGER
                && actor.role() != OperationContext.Role.ADMIN)) {
            return Result.rejected("FORBIDDEN", "Reversal requires manager/admin");
        }
        final DocumentReversalCommand command;
        try {
            command = request.as(DocumentReversalCommand.class);
        } catch (RuntimeException ex) {
            return Result.rejected("INVALID_INPUT", "Invalid reversal request");
        }
        if (!command.targetDocumentId().equals(op.targetId())) {
            return Result.rejected("REFERENCE_INVALID", "Operation target mismatch");
        }
        RecordData target = baseline.find("DOCUMENT", command.targetDocumentId()).orElse(null);
        if (target == null || !"CONFIRMED".equals(target.as(DocumentHeader.class).status())) {
            return Result.rejected("REFERENCE_INVALID", "Target is not a confirmed document");
        }
        if (!changes.removals().isEmpty()) {
            return Result.rejected("INVALID_INPUT", "Reversal must not remove records");
        }
        String dependency = dependencyBlocker(baseline, command.targetDocumentId());
        if (dependency != null) {
            return Result.rejected("DEPENDENCY_BLOCKED", dependency);
        }
        List<RecordData> documents = inserts(changes, "DOCUMENT");
        if (documents.size() != 1) {
            return Result.rejected("INVALID_INPUT", "Exactly one reversal document required");
        }
        DocumentHeader header = documents.get(0).as(DocumentHeader.class);
        if (!"REVERSAL".equals(header.kind()) || !"CONFIRMED".equals(header.status())) {
            return Result.rejected("INVALID_INPUT", "Reversal document kind/status mismatch");
        }
        if (!actor.accountId().equals(header.confirmedBy())) {
            return Result.rejected("FORBIDDEN", "Reversal actor mismatch");
        }
        List<RecordData> reversals = inserts(changes, "REVERSAL");
        if (reversals.size() != 1
                || !command.targetDocumentId().equals(
                        reversals.get(0).data().path("target_document_id").asText())) {
            return Result.rejected("REFERENCE_INVALID", "REVERSAL target mismatch");
        }
        ChangeSet.Patch targetPatch = changes.patches().stream()
                .filter(p -> p.table().equals("DOCUMENT") && p.id().equals(command.targetDocumentId()))
                .findFirst().orElse(null);
        if (targetPatch == null
                || !"VOIDED".equals(((ObjectNode) JsonCodec.tree(targetPatch.changedFields()))
                        .path("status").asText())) {
            return Result.rejected("INVALID_INPUT", "Target must be patched to VOIDED");
        }
        if (changes.inserts().stream().anyMatch(r -> !INSERT_TABLES.contains(r.table()))) {
            return Result.rejected("INVALID_INPUT", "Reversal carries unrelated records");
        }
        for (RecordData record : inserts(changes, "STOCK_ENTRY")) {
            StockEntry reverse = record.as(StockEntry.class);
            if (reverse.reverseOfId() == null) {
                continue;
            }
            StockEntry original = baseline.find("STOCK_ENTRY", reverse.reverseOfId())
                    .orElseThrow(() -> new IllegalArgumentException("Missing original stock"))
                    .as(StockEntry.class);
            if (original.quantityDelta() != -reverse.quantityDelta()
                    || original.position() != reverse.position()) {
                return Result.rejected("REFERENCE_INVALID", "Stock reversal does not match original");
            }
        }
        for (RecordData record : inserts(changes, "MONEY_ENTRY")) {
            MoneyEntry reverse = record.as(MoneyEntry.class);
            if (reverse.reverseOfId() == null) {
                return Result.rejected("INVALID_INPUT", "Reversal money needs reverseOfId");
            }
            MoneyEntry original = baseline.find("MONEY_ENTRY", reverse.reverseOfId())
                    .orElseThrow(() -> new IllegalArgumentException("Missing original money"))
                    .as(MoneyEntry.class);
            if (original.amountSigned().add(reverse.amountSigned()).signum() != 0) {
                return Result.rejected("REFERENCE_INVALID", "Money reversal amount mismatch");
            }
        }
        for (RecordData record : inserts(changes, "REDEMPTION")) {
            Redemption reverse = record.as(Redemption.class);
            if (reverse.effect() != Effect.RELEASE || reverse.reverseOfId() == null) {
                return Result.rejected("INVALID_INPUT", "Reversal redemption must be RELEASE");
            }
            Redemption original = baseline.find("REDEMPTION", reverse.reverseOfId())
                    .orElseThrow(() -> new IllegalArgumentException("Missing original redemption"))
                    .as(Redemption.class);
            if (original.quantity() != reverse.quantity()
                    || original.amount().compareTo(reverse.amount()) != 0) {
                return Result.rejected("REFERENCE_INVALID", "Redemption release does not match original");
            }
        }
        return Result.value(null);
    }

    private String barcodeOf(WorkingCopy baseline, String sourceLineId) {
        return baseline.find("DOC_LINE", sourceLineId)
                .map(r -> r.as(DocumentLine.class).barcode())
                .orElse(null);
    }

    private List<RecordData> inserts(ChangeSet changes, String table) {
        return changes.inserts().stream().filter(r -> r.table().equals(table)).toList();
    }

    private String dependencyBlocker(WorkingCopy baseline, String targetDocumentId) {
        Set<String> targetLines = baseline.records("DOC_LINE").stream()
                .filter(r -> targetDocumentId.equals(r.as(DocumentLine.class).documentId()))
                .map(RecordData::id)
                .collect(java.util.stream.Collectors.toSet());
        if (!targetLines.isEmpty()) {
            for (RecordData record : baseline.records("REDEMPTION")) {
                Redemption redemption = record.as(Redemption.class);
                if (targetLines.contains(redemption.originalSaleLineId())
                        && redemption.reverseOfId() == null) {
                    return "Later aftersale redemption depends on original sale";
                }
            }
            for (RecordData record : baseline.records("STOCK_ENTRY")) {
                StockEntry entry = record.as(StockEntry.class);
                if (!targetLines.contains(entry.sourceLineId())) {
                    continue;
                }
                String entryBarcode = barcodeOf(baseline, entry.sourceLineId());
                for (RecordData other : baseline.records("STOCK_ENTRY")) {
                    StockEntry later = other.as(StockEntry.class);
                    if (other.id().equals(record.id())
                            || later.quantityDelta() >= 0
                            || later.reverseOfId() != null
                            || !Objects.equals(barcodeOf(baseline, later.sourceLineId()), entryBarcode)
                            || later.position() != entry.position()
                            || later.commitOrdinal() <= entry.commitOrdinal()) {
                        continue;
                    }
                    return "Later effective stock movement depends on original stock entry";
                }
            }
        }
        return null;
    }
}
package nz.ac.aut.pdc.supermarket.stock;

import java.time.Instant;
import java.util.HashSet;
