        String raw = prompt(message);
        if (raw == null) {
            return null;
        }
        String value = raw.trim().toLowerCase(Locale.ROOT);
        if ("y".equals(value) || "yes".equals(value)) {
            return Boolean.TRUE;
        }
        if ("n".equals(value) || "no".equals(value)) {
            return Boolean.FALSE;
        }
        output.println("输入错误：请输入 y 或 n");
