        assertEquals(result.code(), Result.Status.VALUE, result.status());
    }

    @Test
    public void tamperedLineQuantityIsRejected() {
        ChangeSet tampered = new ChangeSet(
                changes().inserts().stream()
                        .map(r -> r.table().equals("DOC_LINE")
