            throw new IllegalArgumentException("lossId must not be blank");
        }
        if (barcode == null || barcode.isBlank()) {
            throw new IllegalArgumentException("barcode must not be blank");
        }
        Objects.requireNonNull(position, "position");
        if (quantity < 1) {
            throw new IllegalArgumentException("quantity must be positive");
        }
        Objects.requireNonNull(origin, "origin");
        Objects.requireNonNull(dispositionState, "dispositionState");
    }

    /** 记录处置结果，状态转为 DISPOSED；不保存、不提交。 */
    public LossRecord dispose(String disposition) {
        if (disposition == null || disposition.isBlank()) {
            throw new IllegalArgumentException("disposition must not be blank");
        }
        return new LossRecord(
                lossId, sourceLineId, barcode, position, quantity, origin,
                disposition, LossState.DISPOSED);
    }
}


package nz.ac.aut.pdc.supermarket.aftersale;

import java.time.Instant;
import java.util.List;
import java.util.Objects;

import com.fasterxml.jackson.databind.node.ObjectNode;

import nz.ac.aut.pdc.shared.ChangeSet;
import nz.ac.aut.pdc.shared.DocEvent;
import nz.ac.aut.pdc.shared.DocumentHeader;
import nz.ac.aut.pdc.shared.DocumentLine;
import nz.ac.aut.pdc.shared.JsonCodec;
import nz.ac.aut.pdc.shared.JsonCodec.BusinessRequest;
import nz.ac.aut.pdc.shared.OperationContext;
import nz.ac.aut.pdc.shared.RecordData;
import nz.ac.aut.pdc.shared.Result;
import nz.ac.aut.pdc.shared.SubmissionPort;
import nz.ac.aut.pdc.shared.WorkingCopy;

/** B 负责的售后草稿/读取追溯/取消六参校验器。 */
public final class AftersaleDraftValidator implements SubmissionPort.CommitValidator {

    private final String operation;

    public AftersaleDraftValidator(String operation) {
        this.operation = Objects.requireNonNull(operation, "operation");
    }

    @Override
    public Result<Void> validate(
            OperationContext op,
            OperationContext.ActorContext actor,
            BusinessRequest request,
            WorkingCopy baseline,
            ChangeSet changes,
            Instant acceptedAt) {
        if (!operation.equals(op.operation())) {
            return Result.rejected("INVALID_INPUT", "Wrong draft operation");
        }
        return switch (operation) {
            case AftersaleDraftOperations.CREATE -> validateCreate(op, actor, baseline, changes);
            case AftersaleDraftOperations.READ -> validateRead(op, actor, baseline, changes);
            case AftersaleDraftOperations.CANCEL -> validateCancel(op, actor, baseline, changes);
            default -> Result.rejected("INVALID_INPUT", "Unknown draft operation");
        };
    }

    private Result<Void> validateCreate(
            OperationContext op, OperationContext.ActorContext actor,
            WorkingCopy baseline, ChangeSet changes) {
        if (op.targetId() == null || op.targetId().isBlank()
                || baseline.find("DOCUMENT", op.targetId()).isPresent()) {
            return Result.rejected("REFERENCE_INVALID", "Draft target must be new");
        }
        List<RecordData> documents = inserts(changes, "DOCUMENT");
        if (documents.size() != 1) {
            return Result.rejected("INVALID_INPUT", "Draft creation requires one DOCUMENT");
        }
        DocumentHeader header = documents.get(0).as(DocumentHeader.class);
        if (!"AFTERSALE".equals(header.kind()) || !"DRAFT".equals(header.status())) {
            return Result.rejected("INVALID_INPUT", "Draft must be AFTERSALE DRAFT");
        OperationContext.ActorContext sharedActor =
                new OperationContext.ActorContext(actor.accountId(), SharedRoles.toShared(actor.role()));
        AftersaleDraftService drafts = new AftersaleDraftService(store);
        OperationContext operation = new OperationContext(
                actor.session(), finalKey, AftersaleChangeSetAssembler.OPERATION, aftersaleId);
        AftersaleCommand command = new AftersaleCommand(
                finalKey,
                null,
                List.of(new AftersaleCommandLine(
                        request.saleLineId(), request.kind(), request.quantity(),
                        request.opened(), request.qualityProblem(), request.reasonKind(),
                        request.reasonText(), request.replacementBarcode(),
                        request.replacementQuantity(), false)));
        BusinessRequest finalRequest = BusinessRequest.of(command);
        Result<SubmissionPort.CommitReceipt> prior = store.lookupResult(operation, finalRequest);
        if (prior.status() != Result.Status.NOT_FOUND) {
            if (prior.hasValue()) {
                return OperationFeedback.ok("售后已提交：" + prior.value().requestKey());
            }
            return OperationFeedback.fail("售后未提交：" + prior.code() + " " + prior.detail());
        }

        OperationContext readOp=new OperationContext(actor.session(),readKey,nz.ac.aut.pdc.shared.AftersaleReadRequest.OPERATION,aftersaleId);
        var access=new nz.ac.aut.pdc.supermarket.sales.OriginalSaleAccess(
            session -> store.authenticate(new OperationContext(session,readKey,readOp.operation(),aftersaleId)),idClock,
            new nz.ac.aut.pdc.supermarket.aftersale.AftersaleDraftAccess());
        var traced=access.readForAftersale(store,readOp,new nz.ac.aut.pdc.shared.AftersaleReadRequest(request.saleLineId(),aftersaleId,List.of(request.saleLineId())));
        if(!traced.hasValue()) return OperationFeedback.fail("IF-11 未返回原单："+traced.code()+"；原键 "+finalKey+"；目标 "+aftersaleId);
        Result<WorkingCopy> openResult = store.open(operation);
        if (!openResult.hasValue()) {
            return OperationFeedback.fail("打开工作副本失败：" + openResult.code() + " " + openResult.detail());
        }
        WorkingCopy workingCopy = openResult.value();
        AftersaleService aftersaleService=nz.ac.aut.pdc.supermarket.aftersale.AftersaleEngine.create(workingCopy,idClock,finalKey);
        AftersaleSubmissionService submission = new AftersaleSubmissionService(
                aftersaleService, new AftersaleChangeSetAssembler(), store);
        Result<SubmissionPort.CommitReceipt> result = submission.submit(
                command, workingCopy, operation, sharedActor);
        if (!result.hasValue()) {
            return OperationFeedback.fail("售后未提交：" + result.code() + " " + result.detail());
        }
        return OperationFeedback.ok("售后已提交：" + result.value().requestKey());
"}

