            RecordData.of("DOCUMENT","S-1",new DocumentHeader("S-1","SALE","CONFIRMED","sale-key","fp","acc-1",time.toString(),"acc-1",time.toString(),null)),
            RecordData.of("DOC_LINE","SL-1",new DocumentLine("SL-1","S-1","SALE","00123456",3)),
