package nz.ac.aut.pdc.supermarket.cui;

import java.math.BigDecimal;
import java.util.Objects;

/**
 * CUI 输入格式与基础边界校验。
 *
 * <p>只做"能否解析/格式/基础范围"的检查；业务规则（库存、额度、权限）
 * 由领域服务复核，二者不互相替代。</p>
 */
public final class InputValidator {

    public static final int MIN_QUANTITY = 1;
    public static final int MAX_QUANTITY = 9999;
    public static final BigDecimal MAX_MONEY = new BigDecimal("999999.99");

    public int parseQuantity(String raw) throws InvalidInputException {
        if (raw == null || raw.isBlank()) {
            throw new InvalidInputException("数量不能为空");
        }
        final int value;
        try {
            value = Integer.parseInt(raw.trim());
        } catch (NumberFormatException ex) {
            throw new InvalidInputException("数量必须是整数");
        }
        if (value < MIN_QUANTITY || value > MAX_QUANTITY) {
            throw new InvalidInputException("数量必须在 1–9999 之间");
        }
        return value;
    }

    public BigDecimal parseMoney(String raw) throws InvalidInputException {
        if (raw == null || raw.isBlank()) {
            throw new InvalidInputException("金额不能为空");
        }
        final BigDecimal value;
        try {
            value = new BigDecimal(raw.trim());
        } catch (NumberFormatException ex) {
            throw new InvalidInputException("金额格式不正确");
        }
        if (value.signum() < 0 || value.compareTo(MAX_MONEY) > 0) {
            throw new InvalidInputException("金额必须在 0–999999.99 之间");
        }
        if (value.scale() > 2) {
            throw new InvalidInputException("金额最多保留两位小数");
        }
        return value;
    }

    /** CUI 层可向用户展示的输入错误。 */
    public static final class InvalidInputException extends Exception {
        public InvalidInputException(String message) {
            super(Objects.requireNonNull(message, "message"));
        }
    }
}

package nz.ac.aut.pdc.supermarket.auth;

import java.util.Objects;

/**
 * 认证/身份解析结果，区分成功、业务拒绝与技术失败三态。
 *
 * <p>对应共享规范 v1.02 §3.1 的 IF-01：成功返回可信会话；失败区分
 * {@code INVALID_CREDENTIALS} 与 {@code AUTH_TECHNICAL_FAILURE}。</p>
 */
public sealed interface AuthResult
        permits AuthResult.Success, AuthResult.Rejected, AuthResult.Failed {

    /** 登录/解析成功：可信会话与解析后的身份。 */
    record Success(SessionRef session, String accountId, Role role) implements AuthResult {
        public Success {
            Objects.requireNonNull(session, "session");
            Objects.requireNonNull(accountId, "accountId");
            Objects.requireNonNull(role, "role");
        }
    }

    /** 业务拒绝：凭证错误、会话无效、未登录等。 */
    record Rejected(String code, String message) implements AuthResult {
        public Rejected {
            Objects.requireNonNull(code, "code");
            Objects.requireNonNull(message, "message");
        }
    }

    /** 技术失败：凭证读取/校验故障，不代表用户凭证错误。 */
    record Failed(String code, String message) implements AuthResult {
        public Failed {
            Objects.requireNonNull(code, "code");
            Objects.requireNonNull(message, "message");
        }
    }
}

package nz.ac.aut.pdc.supermarket.auth;

import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * 本地认证实现：内存会话表 + 只读凭证端口。
 *
 * <p>职责边界：只做认证/解析，不写业务数据、不调用业务提交入口。
 * 正式凭证来源由 A 提供只读视图，通过 {@link CredentialStore} 适配。</p>
 */
public final class LocalAuthService implements AuthService {

    private final CredentialStore credentialStore;
    private final PasswordHasher passwordHasher;
    private final Map<String, SessionState> sessions = new ConcurrentHashMap<>();

    public LocalAuthService(CredentialStore credentialStore, PasswordHasher passwordHasher) {
        this.credentialStore = credentialStore;
        this.passwordHasher = passwordHasher;
    }

    @Override
    public AuthResult login(String username, char[] password) {
        if (username == null || username.isBlank() || password == null) {
            return new AuthResult.Rejected("INVALID_CREDENTIALS", "用户名或密码不能为空");
        }
        try {
            Optional<CredentialStore.StoredCredential> credential =
                    credentialStore.findByUsername(username.trim());
            if (credential.isEmpty()) {
                return new AuthResult.Rejected("INVALID_CREDENTIALS", "用户名或密码不正确");
            }
            CredentialStore.StoredCredential stored = credential.get();
            if (!passwordHasher.matches(password, stored.passwordHash())) {
                return new AuthResult.Rejected("INVALID_CREDENTIALS", "用户名或密码不正确");
            }
            String token = UUID.randomUUID().toString();
            SessionRef session = new SessionRef(token);
            sessions.put(token, new SessionState(session, stored.accountId(), stored.role()));
            return new AuthResult.Success(session, stored.accountId(), stored.role());
        } catch (RuntimeException ex) {
            return new AuthResult.Failed("AUTH_TECHNICAL_FAILURE", "认证服务暂时不可用");
        }
    }

    @Override
    public AuthResult resolve(SessionRef session) {
        if (session == null) {
            return new AuthResult.Rejected("AUTH_REQUIRED", "需要登录");
        }
        SessionState state = sessions.get(session.token());
        if (state == null) {
            return new AuthResult.Rejected("AUTH_REQUIRED", "会话无效，请重新登录");
        }
        return new AuthResult.Success(state.session(), state.accountId(), state.role());
    }

    private record SessionState(SessionRef session, String accountId, Role role) {
    }
}

