        return result.status()==Result.Status.SUCCESS ? OperationFeedback.ok("已提交："+result.value().requestKey()+"；单据／行凭证 "+result.value().resultIds())
            : OperationFeedback.fail("未提交："+result.code()+" "+result.detail());
    }
